    const remainder = count % 4;
    for (let s = 0; s < fullSets; s++) {
      pool.push(0, 1, 2, 3);
    }
    const remOptions = [0, 1, 2, 3].sort(() => Math.random() - 0.5);
    for (let r = 0; r < remainder; r++) {
      pool.push(remOptions[r]);
    }
