function runMultiStageVerificationPipeline(rawQuestions, subjectId, targetTopic) {
  const verifiedQuestions = [];
  let passedDirect = 0;
  let healed = 0;
  let replacedFromVault = 0;
  const s = (subjectId || "").toLowerCase();
  const isAphg = s.includes("geography") || s.includes("aphg") || s.includes("human");
  const isApes = s.includes("environmental") || s.includes("apes");
  const isCalculusBc = s.includes("bc") || s.includes("calculus bc");
  const isChem = s.includes("chemistry") || s.includes("chem");
  const isBio = s.includes("biology") || s.includes("bio");
  const isPhys1 = s.includes("physics 1") || s.includes("phys");
  const isLang = s.includes("english") || s.includes("lang");
  const isPsych = s.includes("psych");
  const isCsa = s.includes("computer science a") || s.includes("csa") || s.includes("computer") && !s.includes("principles") && !s.includes("csp");
  const isWhap = s.includes("world history") || s.includes("whap") || s.includes("world") && s.includes("history") || s.includes("history") && !s.includes("u.s.") && !s.includes("us") && !s.includes("euro");
  const isStat = s.includes("statistic") || s.includes("stat");
  const goldenKey = isStat ? "ap-statistics" : isWhap ? "ap-world-history" : isCsa ? "ap-computer-science" : isPsych ? "ap-psychology" : isLang ? "ap-english-lang" : isAphg ? "aphg" : isApes ? "apes" : isCalculusBc ? "ap-calculus-bc" : isChem ? "ap-chemistry" : isBio ? "ap-biology" : isPhys1 ? "ap-physics-1" : s.includes("calculus") ? "ap-calculus-ab" : s;
  const goldenBank = PRISTINE_GOLDEN_QUESTIONS[goldenKey] || PRISTINE_GOLDEN_QUESTIONS[s] || (isStat ? PRISTINE_GOLDEN_QUESTIONS["ap-statistics"] : isWhap ? PRISTINE_GOLDEN_QUESTIONS["ap-world-history"] : isCsa ? PRISTINE_GOLDEN_QUESTIONS["ap-computer-science"] : isPsych ? PRISTINE_GOLDEN_QUESTIONS["ap-psychology"] : isLang ? PRISTINE_GOLDEN_QUESTIONS["ap-english-lang"] : isCalculusBc ? PRISTINE_GOLDEN_QUESTIONS["ap-calculus-bc"] : isChem ? PRISTINE_GOLDEN_QUESTIONS["ap-chemistry"] : isBio ? PRISTINE_GOLDEN_QUESTIONS["ap-biology"] : isPhys1 ? PRISTINE_GOLDEN_QUESTIONS["ap-physics-1"] : isAphg ? PRISTINE_GOLDEN_QUESTIONS["aphg"] : isApes ? PRISTINE_GOLDEN_QUESTIONS["apes"] : PRISTINE_GOLDEN_QUESTIONS["ap-calculus-ab"]) || [];
  for (let idx = 0; idx < rawQuestions.length; idx++) {
    const rawQ = rawQuestions[idx];
    let processedQ = rawQ;
    if (isAphg) {
      processedQ = healAphgQuestion(processedQ);
      healed++;
    }
    const promptStr = String(processedQ.prompt || processedQ.question || "");
    const canonical = resolveCanonicalUnit(
      subjectId,
      processedQ.unitNumber ?? (processedQ.unitTitle || processedQ.unit || targetTopic),
      promptStr,
      idx
    );
    const getFallback = (qIndex) => {
      if (isAphg) {
        return getAphgPristineUnitQuestion(canonical.unitNumber || qIndex % 7 + 1, targetTopic, qIndex);
      }
      if (processedQ.format === "subjective" || Array.isArray(processedQ.parts)) {
        return processedQ;
      }
      return goldenBank[qIndex % goldenBank.length] || processedQ;
    };
    const scopeCheck = verifyCurriculumScope(processedQ, subjectId);
    if (!scopeCheck.inScope) {
      console.warn(`[MultiStageVerification] Q${idx + 1} REJECTED by Scope Gate:`, scopeCheck.reasons);
      const fallback = getFallback(idx);
      verifiedQuestions.push({ ...fallback, id: idx + 1 });
      replacedFromVault++;
      continue;
    }
    const solvabilityCheck = verifyBlindSolvability(processedQ);
    if (!solvabilityCheck.isSolvable) {
      console.warn(`[MultiStageVerification] Q${idx + 1} REJECTED by Blind Solver Gate:`, solvabilityCheck.issues);
      const fallback = getFallback(idx);
      verifiedQuestions.push({ ...fallback, id: idx + 1 });
      replacedFromVault++;
      continue;
    }
    const mathCheck = verifyMathAndFeasibility(processedQ, subjectId);
    if (!mathCheck.isValid) {
      console.warn(`[MultiStageVerification] Q${idx + 1} REJECTED by Math Feasibility Gate:`, mathCheck.issues);
      const fallback = getFallback(idx);
      verifiedQuestions.push({ ...fallback, id: idx + 1 });
      replacedFromVault++;
      continue;
    }
    if (isAphg) {
      const aphgCheck = verifyAphgGeographicalAccuracy(processedQ, targetTopic);
      if (!aphgCheck.isValid) {
        console.warn(`[MultiStageVerification] Q${idx + 1} APHG Geographical Model Gate FAILED:`, aphgCheck.issues);
        if (!aphgCheck.canHeal) {
          console.warn(`[MultiStageVerification] Q${idx + 1} Cannot be safely healed. Replacing with Unit ${canonical.unitNumber} pristine Golden Vault question.`);
          const fallback = getFallback(idx);
          verifiedQuestions.push({ ...fallback, id: idx + 1 });
          replacedFromVault++;
          continue;
        }
      }
    }
    const realPoints = isWhap ? rawQuestions.length === 2 ? idx === 0 ? 7 : 6 : processedQ.totalPoints === 7 || processedQ.totalPoints === 6 || processedQ.totalPoints === 3 ? processedQ.totalPoints : idx % 5 === 0 ? 7 : idx % 5 === 1 ? 6 : 3 : isAphg ? 7 : isApes ? 10 : isPsych ? 7 : calculateRealTotalPoints(processedQ, subjectId);
    const healedQuestion = {
      ...processedQ,
      id: idx + 1,
      totalPoints: realPoints,
      prompt: stripRawSvgMarkup(processedQ.prompt || processedQ.question || ""),
      modelAnswer: stripRawSvgMarkup(processedQ.modelAnswer || ""),
      unitNumber: processedQ.unitNumber && typeof processedQ.unitNumber === "number" ? processedQ.unitNumber : canonical.unitNumber,
      unitTitle: processedQ.unitTitle || canonical.title,
      skill: processedQ.skill && !processedQ.skill.toLowerCase().includes("all units") ? processedQ.skill : `Unit ${canonical.unitNumber}: ${canonical.title}`
    };
    verifiedQuestions.push(healedQuestion);
    passedDirect++;
  }
  return {
    verifiedQuestions,
    stats: {
      total: rawQuestions.length,
      passedDirect,
      healed,
      replacedFromVault
    }
  };
}

